count = 0
for item in data:
    # 同一タイトルの重複登録を防ぐ
    obj, created = Item.objects.get_or_create(
        title=item["title"],
        defaults={
            "media_type": item["media_type"],
            "reason": item["reason"],
            "tags": item["tags"]
        }
    )
    if created:
        count += 1

print(f"✅ 登録完了: {count}件の新規データをデータベースに追加しました！")